use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_char(c: char) -> bool {
    'a' <= c && c <= 'z'
}

spec fn spec_all_lowercase(v: Seq<char>) -> bool {
    if v.len() == 0 {
        false
    } else {
        forall|i: int| 0 <= i < v.len() ==> is_lowercase_char(v[i])
    }
}

fn check_all_lowercase(v: &Vec<char>) -> (result: bool)
    ensures
        result == spec_all_lowercase(v@),
{
    if v.is_empty() {
        return false;
    }
    
    let mut i: usize = 0;
    while i < v.len()
        invariant
            0 <= i <= v.len(),
            forall|j: int| 0 <= j < i ==> is_lowercase_char(v@[j]),
    {
        let c = v[i];
        if !('a' <= c && c <= 'z') {
            return false;
        }
        i = i + 1;
    }
    
    true
}

fn solve(input: Vec<char>) -> (output: Vec<char>)
    ensures
        output@.len() == 1,
        (output@.len() == 1 && (output@[0] == 'a' || output@[0] == 'A')),
        spec_all_lowercase(input@) ==> output@[0] == 'a',
        !spec_all_lowercase(input@) ==> output@[0] == 'A',
{
    let all_lowercase = check_all_lowercase(&input);
    
    if all_lowercase {
        let mut result = Vec::new();
        result.push('a');
        result
    } else {
        let mut result = Vec::new();
        result.push('A');
        result
    }
}

}